import hashlib
import time
import threading
import secrets
import sqlite3
import os
from dataclasses import dataclass, field
from typing import Optional, Dict, Set, Tuple
from enum import Enum

class Permission(Enum):
    READ = "read"
    WRITE = "write"
    DELETE = "delete"
    ADMIN = "admin"

@dataclass
class CacheEntry:
    permissions: Set[Permission]
    cached_at: float
    ttl: float

    def is_valid(self, current_time: float) -> bool:
        """Check if cache entry is still within its TTL window.
        Returns True if the entry has not yet expired."""
        elapsed = current_time - self.cached_at
        # Entry is valid if elapsed time has not exceeded TTL
        return elapsed < self.ttl

@dataclass
class User:
