class SecurePasswordHasher:
    """PBKDF2-based password hashing with per-user salts."""
    ITERATIONS = 100000
    HASH_ALGO = 'sha256'
    SALT_LENGTH = 32

    @classmethod
    def hash_password(cls, password: str) -> Tuple[str, str]:
        salt = secrets.token_hex(cls.SALT_LENGTH)
        hash_val = hashlib.pbkdf2_hmac(
            cls.HASH_ALGO,
            password.encode('utf-8'),
            salt.encode('utf-8'),
            cls.ITERATIONS
        ).hex()
        return hash_val, salt

    @classmethod
    def verify_password(cls, password: str, hash_val: str, salt: str) -> bool:
        computed = hashlib.pbkdf2_hmac(
            cls.HASH_ALGO,
            password.encode('utf-8'),
            salt.encode('utf-8'),
            cls.ITERATIONS
        ).hex()
        return secrets.compare_digest(computed, hash_val)

class PermissionStore:
    """SQLite-backed permission storage with proper parameterization."""
    def __init__(self, db_path: str = ":memory:"):
        self._conn = sqlite3.connect(db_path, check_same_thread=False)
        self._lock = threading.Lock()
        self._setup_schema()

    def _setup_schema(self):
        with self._lock:
            self._conn.execute("""
                CREATE TABLE IF NOT EXISTS user_permissions (
                    user_id TEXT NOT NULL,
                    permission TEXT NOT NULL,
                    granted_at REAL NOT NULL,
                    revoked_at REAL,
                    PRIMARY KEY (user_id, permission)
                )
            """)
            self._conn.commit()

    def grant_permission(self, user_id: str, permission: Permission, timestamp: float):
        with self._lock:
            self._conn.execute(
                "INSERT OR REPLACE INTO user_permissions (user_id, permission, granted_at, revoked_at) VALUES (?, ?, ?, NULL)",
                (user_id, permission.value, timestamp)
            )
            self._conn.commit()

    def revoke_permission(self, user_id: str, permission: Permission, timestamp: float):
        with self._lock:
            self._conn.execute(
                "UPDATE user_permissions SET revoked_at = ? WHERE user_id = ? AND permission = ? AND revoked_at IS NULL",
                (timestamp, user_id, permission.value)
            )
            self._conn.commit()

    def get_active_permissions(self, user_id: str) -> Set[Permission]:
        with self._lock:
            cursor = self._conn.execute(
                "SELECT permission FROM user_permissions WHERE user_id = ? AND revoked_at IS NULL",
                (user_id,)
            )
            return {Permission(row[0]) for row in cursor.fetchall()}

class AuthorizationService:
    """Caching authorization service with TTL-based invalidation.

    The cache reduces database load by storing permission lookups
    for a configurable TTL period. When the cache entry expires,
    permissions are re-fetched from the authoritative store.
    """
    DEFAULT_CACHE_TTL = 300.0  # 5 minutes

    def __init__(self, permission_store: PermissionStore, cache_ttl: float = None):
        self._store = permission_store
        self._cache: Dict[str, CacheEntry] = {}
        self._cache_lock = threading.Lock()
        self._cache_ttl = cache_ttl if cache_ttl is not None else self.DEFAULT_CACHE_TTL

    def _get_cached_permissions(self, user_id: str, current_time: float) -> Optional[Set[Permission]]:
        """Retrieve permissions from cache if entry is still valid."""
        with self._cache_lock:
            entry = self._cache.get(user_id)
            if entry is not None and entry.is_valid(current_time):
                return entry.permissions
            return None

    def _update_cache(self, user_id: str, permissions: Set[Permission], current_time: float):
        """Store fresh permissions in the cache."""
        with self._cache_lock:
            self._cache[user_id] = CacheEntry(
                permissions=permissions.copy(),
                cached_at=current_time,
                ttl=self._cache_ttl
            )

    def invalidate_cache(self, user_id: str):
        """Explicitly invalidate a user's cached permissions."""
        with self._cache_lock:
            self._cache.pop(user_id, None)

    def check_permission(self, user_id: str, required: Permission, current_time: float = None) -> bool:
        """Check if user has the required permission.

        Uses cached permissions if available and valid,
        otherwise fetches from the permission store.
        """
        if current_time is None:
            current_time = time.time()

        # Try cache first
        cached = self._get_cached_permissions(user_id, current_time)
        if cached is not None:
            return required in cached

        # Cache miss or expired - fetch from store
        permissions = self._store.get_active_permissions(user_id)
        self._update_cache(user_id, permissions, current_time)
        return required in permissions

class DocumentService:
    """Business logic layer for document operations."""
    def __init__(self, auth_service: AuthorizationService):
        self._auth = auth_service
        self._documents: Dict[str, dict] = {}
        self._doc_lock = threading.Lock()

    def create_document(self, user_id: str, doc_id: str, content: str, current_time: float = None) -> dict:
        if not doc_id or not doc_id.isalnum():
            return {"error": "Invalid document ID"}
        if len(content) > 1_000_000:
            return {"error": "Content too large"}

        if not self._auth.check_permission(user_id, Permission.WRITE, current_time):
            return {"error": "Permission denied", "required": "write"}

        with self._doc_lock:
            if doc_id in self._documents:
                return {"error": "Document already exists"}
            self._documents[doc_id] = {
                "id": doc_id,
                "content": content,
                "created_by": user_id,
                "created_at": current_time or time.time()
            }
        return {"success": True, "doc_id": doc_id}

    def delete_document(self, user_id: str, doc_id: str, current_time: float = None) -> dict:
        if not doc_id or not doc_id.isalnum():
            return {"error": "Invalid document ID"}

        if not self._auth.check_permission(user_id, Permission.DELETE, current_time):
            return {"error": "Permission denied", "required": "delete"}

        with self._doc_lock:
            if doc_id not in self._documents:
                return {"error": "Document not found"}
            del self._documents[doc_id]
        return {"success": True}

def main():
    # Setup
    store = PermissionStore()
    auth = AuthorizationService(store, cache_ttl=300.0)
    docs = DocumentService(auth)

    # Create user with write permission
    t0 = 1000.0
    store.grant_permission("user1", Permission.WRITE, t0)
    store.grant_permission("user1", Permission.READ, t0)

    # User creates a document
    result = docs.create_document("user1", "doc1", "Hello World", current_time=t0 + 1)
    print(f"Create doc: {result}")

    # Admin revokes write permission
    store.revoke_permission("user1", Permission.WRITE, t0 + 10)
    # Note: cache is not explicitly invalidated here (relies on TTL expiry)

    # User tries to create another document after revocation
    result = docs.create_document("user1", "doc2", "Should this work?", current_time=t0 + 15)
    print(f"Create doc after revoke: {result}")

if __name__ == "__main__":
    main()
